require __DIR__.'/../bootstrap.php'; $u=require_login(); if($_SERVER['REQUEST_METHOD']!=='POST') respond(['success'=>false,'message'=>'Method tidak diizinkan.'],405); check_csrf(); $id=(int)(json_input()['reward_id']??0); if($id<1) respond(['success'=>false,'message'=>'Reward tidak valid.'],422);
try{$pdo->beginTransaction(); $q=$pdo->prepare('SELECT points FROM users WHERE id=? FOR UPDATE');$q->execute([$u['id']]);$user=$q->fetch();$q=$pdo->prepare('SELECT id,name,points_cost,stock FROM rewards WHERE id=? AND is_active=1 FOR UPDATE');$q->execute([$id]);$r=$q->fetch();if(!$r){$pdo->rollBack();respond(['success'=>false,'message'=>'Reward tidak tersedia.'],404);}if($r['stock']!==null&&(int)$r['stock']<1){$pdo->rollBack();respond(['success'=>false,'message'=>'Stok reward habis.'],409);}if((int)$user['points']<(int)$r['points_cost']){$pdo->rollBack();respond(['success'=>false,'message'=>'Poin kamu belum cukup.'],422);}$pdo->prepare('UPDATE users SET points=points-? WHERE id=?')->execute([$r['points_cost'],$u['id']]);$pdo->prepare('INSERT INTO redemptions(user_id,reward_id,points_spent,status) VALUES(?,?,?,\'pending\')')->execute([$u['id'],$id,$r['points_cost']]);if($r['stock']!==null)$pdo->prepare('UPDATE rewards SET stock=stock-1 WHERE id=?')->execute([$id]);$pdo->commit();respond(['success'=>true,'message'=>'Penukaran berhasil diajukan.']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();respond(['success'=>false,'message'=>'Penukaran gagal diproses.'],500);}
